    /* =================================================================
       REJTETT HOZAMOK (t6). Atveve a TW-Calc scriptjebol (The-West-Scripts/
       TW-Calc-Script, src/components/nearest-jobs/hid-tasks.ts; utolso
       modositas 2025-02-15), a szerzok engedelyevel. 379 targy, a kulcs a
       targy alapazonositoja (item_id / 1000). Egy sor:
         - szam kulcs (<= 205): munka azonositoja, erteke esely ("10%"),
           esemenyidoszak, megjegyzes, vagy ures;
         - 999: nem munka, hanem esemeny (erteke az idoszak);
         - eq, eq2: viselni kell ezt a targyat (alapazonosito);
         - inv: { alapazonosito: darab } ennyi legyen a taskaban.
       MERT (2026-09-25): a jatek ezekrol a targyakrol (spec_type nem
       "mapdrop") SEMMIT nem tud, a JobList.getJobsByItemId ures; es a
       feltetel (pl. Lotuszszirom a termekhelyen) a kliensen sehol nem
       latszik. A TW-Calc a JobList-et is felulirja ezzel a tablaval, ezert
       a nem mapdrop targyaknal a SAJAT tablankat nezzuk, nem a JobList-et.
       ================================================================= */
