    const KS_NAP_IDX = { "vasárnap": 0, "hétfő": 1, "kedd": 2, "szerda": 3, "csütörtök": 4, "péntek": 5, "szombat": 6 };
    const KS_NAP_NEV = ["vasárnap", "hétfő", "kedd", "szerda", "csütörtök", "péntek", "szombat"];
