        if (r && ab.datum && r.nyitva) r.zar = Math.min(r.zar, (ab.datum.veg - W) / 60000);
        if (r && ab.datum && !r.nyitva && most.fal + r.nyit * 60000 >= ab.datum.veg) return null;
